import { asUint8Array } from "@ndn/util";
import { WebSocket as WsWebSocket } from "ws";
export function makeWebSocket(uri) {
    if (globalThis.WebSocket) {
        return new WebSocket(uri, []);
    }
    return new WsWebSocket(uri, [], { perMessageDeflate: false });
}
export function changeBinaryType(sock) {
    sock.binaryType = "arraybuffer";
    if (sock instanceof WsWebSocket) {
        sock.binaryType = "nodebuffer";
    }
}
export function extractMessage(evt) {
    return asUint8Array(evt.data);
}
